corrected_code:
const Redis = require('ioredis');
const redis = new Redis(process.env.REDIS_URL);

router.delete('/api/sessions/:sessionId/terminate', checkSessionAuth, async (req, res) => {
  const { sessionId } = req.params;

  const sessionKey = `sess:${sessionId}`;
  const rawData = await redis.get(sessionKey);
  if (!rawData) {
    return res.status(404).json({ error: 'Session does not exist' });
  }

  const session = JSON.parse(rawData);
  if (session.passport?.user !== req.user.id && session.userId !== req.user.id) {
    return res.status(403).json({ error: 'Forbidden: you cannot terminate sessions of other users' });
  }

  await redis.del(sessionKey);
  return res.json({ message: 'Session invalidated', sessionId });
});
